     4	export function checkout(cart: Cart, skus: Array<[string, number]>, discountPct: number): number {
     5		for (const [sku, qty] of skus) {
     6			if (!reserve(sku, qty)) { continue; }
     7		}
     8		return cart.total(discountPct);
